-- Run from the server/ folder: luajit tests/passivetree_layout_test.lua (no engine; CI runs it with luajit and lua5.3)
-- The whole passive tree, client against server (client/overlay/modules/game_passivetree/treedata against
-- data/scripts/chaos/passivetree_data.lua, generated by tools/gen_passivetree_data.lua):
--   * links: every link the client knows (`out` and `inputs`; a class section's start stands for the root, hidden nodes
--     have none) is a server link and every server link is a client link;
--   * drawing: every link is drawn (the client draws connectors from `out` only), except the root's own links (its
--     nodes sit on its ring); no node lists itself;
--   * class sections (625-664): each line's nodes are reachable from its start only through its own section, and link
--     to nothing outside it;
--   * layout, for nodes seen together (the four class sections share one place; each player sees only its line):
--     no two nodes overlap, no straight link runs through a third node, no shown node is without links, every node's
--     group exists; the class sections keep clear of the rest of the tree.
-- Node positions are computed as the client does (passivetree.lua: group centre + orbit radius at orbitIndex degrees);
-- node sizes from passivetree.otui (27 small, 38 notable, 41 rare, 60 keystone; start medallions 245 root, 150 class).
local TD = "../client/overlay/modules/game_passivetree/treedata/"
local fh = io.open(TD .. "nodes.lua")
if not fh then
	print("passivetree_layout_test: client tree not found, skipped")
	return
end
fh:close()
dofile(TD .. "groups.lua")
dofile(TD .. "nodes.lua")
local G, N = getTreeGroups(), getTreeNodes()
local S = dofile("data/scripts/chaos/passivetree_data.lua")

local fails, checks = {}, 0
local function check(cond, what)
	checks = checks + 1
	if not cond then
		fails[#fails + 1] = what
	end
end

local ORBIT = {[0] = 0, 60, 80, 120, 191, 250, 290}
local pos, size = {}, {}
for id, n in pairs(N) do
	local g = G[n.group]
	check(g ~= nil, "node " .. id .. ": group " .. tostring(n.group) .. " exists")
	if g then
		local x, y = g.x, g.y
		if not n.isStartNode then
			local a = (n.orbitIndex or 0) * math.pi / 180
			local d = (n.orbitDist and n.orbitDist > 0) and n.orbitDist or ORBIT[n.orbit or 0]
			x, y = g.x + math.sin(a) * d, g.y - math.cos(a) * d
		end
		pos[id] = {x, y}
	end
	size[id] = n.isStartNode and (n.line and 150 or 245) or (n.isDivine and 60) or (n.isRare and 41)
		or ((n.isUncommon or n.isVeryRare or n.isMythic) and 38) or 27
end

local function key(a, b)
	if a > b then
		a, b = b, a
	end
	return a .. "-" .. b
end
local function ends(k)
	local a, b = k:match("(%d+)-(%d+)")
	return tonumber(a), tonumber(b)
end
local function isRoot(id)
	return N[id].isStartNode and not N[id].line
end
local function serverId(id)
	return N[id].isStartNode and S.root or id
end
local function together(a, b)
	return not N[a].line or not N[b].line or N[a].line == N[b].line
end

-- ------------------------------------------------------------------ links
local links, drawn = {}, {}
for id, n in pairs(N) do
	if not n.hidden then
		for _, list in ipairs({n.out or {}, n.inputs or {}}) do
			for _, o in pairs(list) do
				check(o ~= id, "node " .. id .. " links itself")
				check(N[o] ~= nil and not N[o].hidden, "node " .. id .. " links a missing or hidden node " .. tostring(o))
				if o ~= id and N[o] and not N[o].hidden then
					links[key(id, o)] = true
				end
			end
		end
		for _, o in pairs(n.out or {}) do
			if N[o] then
				drawn[key(id, o)] = true
			end
		end
	else
		check(#(n.out or {}) == 0 and #(n.inputs or {}) == 0, "hidden node " .. id .. " has no links")
		check(S.nodes[id] == nil, "hidden node " .. id .. " is not a server node")
	end
end
local clientServer = {}
for k in pairs(links) do
	local a, b = ends(k)
	check(drawn[k] or isRoot(a) or isRoot(b), "link " .. k .. " is drawn (in an `out` list)")
	local sa, sb = serverId(a), serverId(b)
	if sa ~= sb then
		clientServer[key(sa, sb)] = true
		check(S.nodes[sa] ~= nil and S.nodes[sb] ~= nil, "link " .. k .. ": both ends are server nodes")
	end
end
local serverLinks = {}
for id, sn in pairs(S.nodes) do
	for _, o in ipairs(sn.n) do
		serverLinks[key(id, o)] = true
	end
end
for k in pairs(clientServer) do
	check(serverLinks[k], "client link " .. k .. " is accepted by the server")
end
for k in pairs(serverLinks) do
	check(clientServer[k], "server link " .. k .. " is a client link")
end
for id in pairs(S.nodes) do
	check(N[id] ~= nil and not N[id].isStartNode or id == S.root, "server node " .. id .. " is a client node")
end

-- ------------------------------------------------------------------ class sections
local starts = {}
for id, n in pairs(N) do
	if n.isStartNode and n.line then
		starts[n.line] = id
	end
end
local sectionCount = 0
for line, start in pairs(starts) do
	sectionCount = sectionCount + 1
	local members = {}
	for id, n in pairs(N) do
		if n.line == line then
			members[id] = true
		end
	end
	-- breadth first from the start through this section's nodes only
	local seen, queue, head = {[start] = true}, {start}, 1
	while head <= #queue do
		local id = queue[head]
		head = head + 1
		for k in pairs(links) do
			local a, b = ends(k)
			local other = (a == id and b) or (b == id and a) or nil
			if other then
				check(members[other], line .. ": node " .. id .. " links " .. other .. " outside its section")
				if members[other] and not seen[other] then
					seen[other] = true
					queue[#queue + 1] = other
				end
			end
		end
	end
	for id in pairs(members) do
		check(seen[id], line .. ": node " .. id .. " is reachable from the start " .. start)
	end
	-- on the server the start is the root: the first node hangs on it, nothing else of the section does
	for id in pairs(members) do
		if id ~= start then
			local onRoot = false
			for _, o in ipairs(S.nodes[id].n) do
				onRoot = onRoot or o == S.root
			end
			local fromStart = links[key(start, id)] == true
			check(onRoot == fromStart, line .. ": node " .. id .. " is on the server root exactly when it is on the start")
		end
	end
end
check(sectionCount == 4, "four class sections")

-- ------------------------------------------------------------------ layout
local ids = {}
for id, n in pairs(N) do
	if not n.hidden and pos[id] then
		ids[#ids + 1] = id
	end
end
table.sort(ids)
local function dist(a, b)
	return math.sqrt((pos[a][1] - pos[b][1]) ^ 2 + (pos[a][2] - pos[b][2]) ^ 2)
end
for i = 1, #ids do
	for j = i + 1, #ids do
		local a, b = ids[i], ids[j]
		if together(a, b) and not (N[a].isStartNode and N[b].isStartNode) then
			-- the root's ring nodes sit on its medallion on purpose; any other node keeps off a start medallion
			local onRootRing = (isRoot(a) or isRoot(b))
			if not onRootRing then
				check(dist(a, b) >= (size[a] + size[b]) / 2, string.format("nodes %d and %d overlap (%.0f apart)", a, b, dist(a, b)))
			end
		end
	end
end
local function segDist(c, a, b)
	local ax, ay, bx, by, px, py = pos[a][1], pos[a][2], pos[b][1], pos[b][2], pos[c][1], pos[c][2]
	local dx, dy = bx - ax, by - ay
	local t = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)
	if t <= 0 or t >= 1 then
		return math.huge
	end
	return math.sqrt((px - (ax + t * dx)) ^ 2 + (py - (ay + t * dy)) ^ 2)
end
for k in pairs(drawn) do
	local a, b = ends(k)
	local arc = N[a].group == N[b].group and N[a].orbit == N[b].orbit and not N[a].isStartNode and not N[b].isStartNode
	if not arc and not isRoot(a) and not isRoot(b) and not N[a].hidden and not N[b].hidden then
		for _, c in ipairs(ids) do
			if c ~= a and c ~= b and together(c, a) and together(c, b) and not isRoot(c) then
				check(segDist(c, a, b) >= size[c] / 2, "link " .. k .. " runs through node " .. c)
			end
		end
	end
end
local degree = {}
for k in pairs(links) do
	local a, b = ends(k)
	degree[a], degree[b] = (degree[a] or 0) + 1, (degree[b] or 0) + 1
end
for _, id in ipairs(ids) do
	check((degree[id] or 0) > 0, "shown node " .. id .. " has links")
end
-- the class sections keep clear of the rest of the tree (a margin of 150 around every other node)
for _, id in ipairs(ids) do
	if N[id].line then
		for _, o in ipairs(ids) do
			if not N[o].line then
				check(dist(id, o) >= (size[id] + size[o]) / 2 + 150, "class node " .. id .. " keeps clear of node " .. o)
			end
		end
	end
end

if #fails > 0 then
	for i = 1, math.min(#fails, 40) do
		print("FAIL " .. fails[i])
	end
	error(#fails .. " of " .. checks .. " checks failed")
end
print("passivetree_layout_test: " .. checks .. " checks, OK")
